public class SaxonAnalysis {

    static final String OUTPUT_DIR = "/analysis-results";

    public static void main(String[] args) {
        String appJar = args.length > 0 ? args[0] : "/workspace/Saxon-HE/12/Java/saxon-jar/saxon-he-12.9.jar";
        String exclusionFilePath = OUTPUT_DIR + "/Java60RegressionExclusions.txt";

        // Ensure output directory exists
        new File(OUTPUT_DIR).mkdirs();

        // Create exclusion file
        createExclusionFile(exclusionFilePath);

        File exclusionFile = new File(exclusionFilePath);

        try {
            // Step 1: Create analysis scope
            System.out.println("=== WALA Static Analysis of Saxon-HE ===");
            System.out.println("Target JAR: " + appJar);
            System.out.println();

            System.out.println("[1/6] Creating analysis scope...");
            AnalysisScope scope = AnalysisScopeReader.instance.makeJavaBinaryAnalysisScope(
                    appJar, exclusionFile);

            // Step 2: Build class hierarchy
            System.out.println("[2/6] Building class hierarchy...");
            ClassHierarchy cha = ClassHierarchyFactory.make(scope);

            int numClasses = 0;
            for (var cls : cha) {
                if (cls.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    numClasses++;
                }
            }
            System.out.println("  Application classes: " + numClasses);

            // Count methods and fields
            int numMethods = 0;
            int numFields = 0;
            int numInterfaces = 0;
            int numConcreteClasses = 0;
            int numAbstractClasses = 0;
            for (var cls : cha) {
                if (!cls.getClassLoader().getReference().equals(ClassLoaderReference.Application)) continue;
                if (cls.isInterface()) {
                    numInterfaces++;
                } else if (cls.isAbstract()) {
                    numAbstractClasses++;
                } else {
                    numConcreteClasses++;
                }
                numMethods += cls.getDeclaredMethods().size();
                numFields += cls.getDeclaredInstanceFields().size() + cls.getDeclaredStaticFields().size();
            }
            System.out.println("  Interfaces: " + numInterfaces);
            System.out.println("  Abstract classes: " + numAbstractClasses);
            System.out.println("  Concrete classes: " + numConcreteClasses);
            System.out.println("  Total methods: " + numMethods);
            System.out.println("  Total fields: " + numFields);

            // Step 3: Set up entrypoints
            System.out.println("[3/6] Setting up entrypoints...");
            Iterable<Entrypoint> entrypoints = Util.makeMainEntrypoints(cha);
            int entrypointCount = 0;
            for (var ep : entrypoints) {
                entrypointCount++;
            }
            System.out.println("  Entrypoints (main methods): " + entrypointCount);

            // Step 4: Build call graph using 0-CFA
            System.out.println("[4/6] Building call graph (0-CFA)...");
            AnalysisOptions options = new AnalysisOptions(scope, entrypoints);
            IAnalysisCacheView cache = new AnalysisCacheImpl();

            CallGraphBuilder<InstanceKey> builder = Util.makeZeroCFABuilder(
                    JavaLanguage.get(), options, cache, cha, null, null);
            CallGraph cg = builder.makeCallGraph(options, null);

            System.out.println("  " + CallGraphStats.getStats(cg));

            // Step 5: Perform pointer analysis (comes with the call graph builder)
            System.out.println("[5/6] Extracting pointer analysis...");
            PointerAnalysis<InstanceKey> pa = builder.getPointerAnalysis();

            // Step 6: Collect and output results
            System.out.println("[6/6] Generating analysis reports...");
            generateReports(cg, cha, pa, appJar);

            System.out.println("=== Analysis Complete ===");
            System.out.println("Results saved to: " + OUTPUT_DIR);

        } catch (ClassHierarchyException e) {
            System.err.println("ClassHierarchyException: " + e.getMessage());
            e.printStackTrace();
        } catch (CancelException e) {
            System.err.println("CancelException: " + e.getMessage());
            e.printStackTrace();
        } catch (IOException e) {
            System.err.println("IOException: " + e.getMessage());
            e.printStackTrace();
        } catch (Exception e) {
            System.err.println("Exception: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private static void createExclusionFile(String path) {
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("java/awt/.*");
            pw.println("javax/.*");
            pw.println("sun/.*");
            pw.println("com/sun/.*");
            pw.println("java/beans/.*");
            pw.println("java/lang/invoke/.*");
            pw.println("org/w3c/dom/.*");
            pw.println("org/xml/sax/.*");
            pw.println("javax/xml/.*");
            pw.println("org/junit/.*");
            pw.println("org/hamcrest/.*");
            pw.println("org/mockito/.*");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void generateReports(CallGraph cg, ClassHierarchy cha, 
                                        PointerAnalysis<InstanceKey> pa, String appJar) throws IOException {
        // Report 1: Call graph statistics
        generateCallGraphStats(cg, appJar);

        // Report 2: Class hierarchy analysis
        generateClassHierarchyReport(cha, appJar);

        // Report 3: Call graph edges (application methods only)
        generateCallGraphEdges(cg);

        // Report 4: Method-level analysis summary
        generateMethodAnalysis(cg);

        // Report 5: Package-level analysis
        generatePackageAnalysis(cg);

        // Report 6: Pointer analysis summary
        generatePointerAnalysisSummary(pa);

        // Report 7: Complete summary
        generateSummaryReport(cg, cha, pa, appJar);
    }

    private static void generateCallGraphStats(CallGraph cg, String appJar) throws IOException {
        String path = OUTPUT_DIR + "/callgraph-stats.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Call Graph Statistics for Saxon-HE");
            pw.println("========================================");
            pw.println("Target: " + appJar);
            pw.println("Analysis: 0-CFA (Zero-Container-Sensitive)");
            pw.println();
            pw.println(CallGraphStats.getStats(cg));
            pw.println();

            int appNodes = 0;
            int primordialNodes = 0;
            int totalEdges = 0;
            int appEdges = 0;
            int maxInDegree = 0;
            int maxOutDegree = 0;
            CGNode maxOutNode = null;

            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodes++;
                } else {
                    primordialNodes++;
                }

                int outDeg = cg.getSuccNodeCount(node);
                int inDeg = cg.getPredNodeCount(node);
                totalEdges += outDeg;
                if (outDeg > maxOutDegree) {
                    maxOutDegree = outDeg;
                    maxOutNode = node;
                }
                if (inDeg > maxInDegree) {
                    maxInDegree = inDeg;
                }
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appEdges += outDeg;
                }
            }

            pw.println("=== Detailed Statistics ===");
            pw.println("Total nodes: " + cg.getNumberOfNodes());
            pw.println("Application nodes: " + appNodes);
            pw.println("Primordial/Library nodes: " + primordialNodes);
            pw.println("Total edges: " + totalEdges);
            pw.println("Application edges: " + appEdges);
            pw.println("Max in-degree: " + maxInDegree);
            pw.println("Max out-degree: " + maxOutDegree);
            if (maxOutNode != null) {
                pw.println("Max out-degree node: " + maxOutNode);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generateClassHierarchyReport(ClassHierarchy cha, String appJar) throws IOException {
        String path = OUTPUT_DIR + "/class-hierarchy-report.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Class Hierarchy Report for Saxon-HE");
            pw.println("========================================");
            pw.println("Target: " + appJar);
            pw.println();

            List<String> appClasses = new ArrayList<>();
            Map<String, Integer> packageCounts = new HashMap<>();
            int interfaces = 0, abstractClasses = 0, concreteClasses = 0;
            int totalMethods = 0, totalFields = 0;

            for (var cls : cha) {
                if (!cls.getClassLoader().getReference().equals(ClassLoaderReference.Application)) continue;

                String className = cls.getName().toString();
                appClasses.add(className);

                String pkg = getPackage(className);
                packageCounts.merge(pkg, 1, Integer::sum);

                if (cls.isInterface()) interfaces++;
                else if (cls.isAbstract()) abstractClasses++;
                else concreteClasses++;

                totalMethods += cls.getDeclaredMethods().size();
                totalFields += cls.getDeclaredInstanceFields().size() + cls.getDeclaredStaticFields().size();
            }

            Collections.sort(appClasses);

            pw.println("=== Summary ===");
            pw.println("Total application classes: " + appClasses.size());
            pw.println("  Interfaces: " + interfaces);
            pw.println("  Abstract classes: " + abstractClasses);
            pw.println("  Concrete classes: " + concreteClasses);
            pw.println("  Total methods: " + totalMethods);
            pw.println("  Total fields: " + totalFields);
            pw.println();

            pw.println("=== Package Distribution ===");
            List<Map.Entry<String, Integer>> sortedPkgs = new ArrayList<>(packageCounts.entrySet());
            sortedPkgs.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
            for (var entry : sortedPkgs) {
                pw.println("  " + entry.getKey() + ": " + entry.getValue() + " classes");
            }
            pw.println();

            pw.println("=== All Application Classes ===");
            for (String cls : appClasses) {
                pw.println("  " + cls);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generateCallGraphEdges(CallGraph cg) throws IOException {
        String path = OUTPUT_DIR + "/callgraph-edges.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Call Graph Edges (Application Methods Only)");
            pw.println("========================================");
            pw.println();

            List<String> edges = new ArrayList<>();
            for (CGNode src : cg) {
                if (!src.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) continue;
                for (CGNode dst : cg) {
                    if (cg.hasEdge(src, dst)) {
                        if (dst.getMethod().getDeclaringClass().getClassLoader().getReference()
                                .equals(ClassLoaderReference.Application)) {
                            edges.add(src.getMethod().getSignature() + " -> " + dst.getMethod().getSignature());
                        }
                    }
                }
            }
            Collections.sort(edges);
            pw.println("Total application-to-application edges: " + edges.size());
            pw.println();
            for (String edge : edges) {
                pw.println(edge);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generateMethodAnalysis(CallGraph cg) throws IOException {
        String path = OUTPUT_DIR + "/method-analysis.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Method-Level Analysis for Saxon-HE");
            pw.println("========================================");
            pw.println();

            // Collect application method nodes with their call counts
            List<MethodStat> methodStats = new ArrayList<>();
            for (CGNode node : cg) {
                if (!node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) continue;
                int callers = cg.getPredNodeCount(node);
                int callees = cg.getSuccNodeCount(node);
                methodStats.add(new MethodStat(
                    node.getMethod().getSignature(),
                    callers,
                    callees
                ));
            }

            // Sort by callers (most called methods)
            methodStats.sort(Comparator.comparingInt(MethodStat::getCallers).reversed());

            pw.println("=== Most Called Methods (Top 50) ===");
            pw.println("Callers | Callees | Method Signature");
            pw.println("--------|---------|----------------");
            int limit = Math.min(50, methodStats.size());
            for (int i = 0; i < limit; i++) {
                MethodStat ms = methodStats.get(i);
                pw.printf("%7d | %7d | %s%n", ms.callers, ms.callees, ms.signature);
            }
            pw.println();

            // Sort by callees (methods that call the most other methods)
            methodStats.sort(Comparator.comparingInt(MethodStat::getCallees).reversed());

            pw.println("=== Methods Calling Most Other Methods (Top 50) ===");
            pw.println("Callers | Callees | Method Signature");
            pw.println("--------|---------|----------------");
            limit = Math.min(50, methodStats.size());
            for (int i = 0; i < limit; i++) {
                MethodStat ms = methodStats.get(i);
                pw.printf("%7d | %7d | %s%n", ms.callers, ms.callees, ms.signature);
            }
            pw.println();

            pw.println("=== Method Statistics ===");
            pw.println("Total application methods in call graph: " + methodStats.size());

            int totalCallers = methodStats.stream().mapToInt(MethodStat::getCallers).sum();
            int totalCallees = methodStats.stream().mapToInt(MethodStat::getCallees).sum();
            pw.println("Total caller edges: " + totalCallers);
            pw.println("Total callee edges: " + totalCallees);

            double avgCallers = methodStats.size() > 0 ? (double) totalCallers / methodStats.size() : 0;
            double avgCallees = methodStats.size() > 0 ? (double) totalCallees / methodStats.size() : 0;
            pw.println("Average callers per method: " + String.format("%.2f", avgCallers));
            pw.println("Average callees per method: " + String.format("%.2f", avgCallees));
        }
        System.out.println("  Saved: " + path);
    }

    private static void generatePackageAnalysis(CallGraph cg) throws IOException {
        String path = OUTPUT_DIR + "/package-analysis.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Package-Level Call Analysis for Saxon-HE");
            pw.println("========================================");
            pw.println();

            Map<String, PackageStat> packageStats = new HashMap<>();

            for (CGNode node : cg) {
                if (!node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) continue;

                String className = node.getMethod().getDeclaringClass().getName().toString();
                String pkg = getPackage(className);

                PackageStat ps = packageStats.computeIfAbsent(pkg, k -> new PackageStat(pkg));
                ps.methodCount++;
                ps.callers += cg.getPredNodeCount(node);
                ps.callees += cg.getSuccNodeCount(node);
            }

            List<PackageStat> stats = new ArrayList<>(packageStats.values());
            stats.sort(Comparator.comparingInt(PackageStat::getMethodCount).reversed());

            pw.println("=== Package Statistics ===");
            pw.println("Package | Methods | Total Callers | Total Callees");
            pw.println("--------|---------|----------------|---------------");
            for (PackageStat ps : stats) {
                pw.printf("%s | %7d | %14d | %14d%n", ps.packageName, ps.methodCount, ps.callers, ps.callees);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generatePointerAnalysisSummary(PointerAnalysis<InstanceKey> pa) throws IOException {
        String path = OUTPUT_DIR + "/pointer-analysis-summary.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Pointer Analysis Summary for Saxon-HE");
            pw.println("========================================");
            pw.println();

            int totalPointerKeys = 0;
            int appPointerKeys = 0;
            Map<String, Integer> instanceTypeCounts = new HashMap<>();
            Set<String> appInstanceTypes = new HashSet<>();

            for (var pk : pa) {
                totalPointerKeys++;
                var ik = pa.getPointsToSet(pk);
                if (ik == null) continue;
                for (var instance : ik) {
                    String concreteType = instance.getConcreteType().getName().toString();
                    instanceTypeCounts.merge(concreteType, 1, Integer::sum);
                    if (instance.getConcreteType().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        appInstanceTypes.add(concreteType);
                    }
                }
            }

            pw.println("=== Pointer Analysis Statistics ===");
            pw.println("Total pointer keys: " + totalPointerKeys);
            pw.println("Total distinct instance types: " + instanceTypeCounts.size());
            pw.println("Application instance types: " + appInstanceTypes.size());
            pw.println();

            pw.println("=== Top 50 Most Allocated Types ===");
            List<Map.Entry<String, Integer>> sortedTypes = new ArrayList<>(instanceTypeCounts.entrySet());
            sortedTypes.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
            int limit = Math.min(50, sortedTypes.size());
            for (int i = 0; i < limit; i++) {
                var entry = sortedTypes.get(i);
                pw.println("  " + entry.getValue() + " : " + entry.getKey());
            }
            pw.println();

            pw.println("=== Application Instance Types ===");
            List<String> sortedAppTypes = new ArrayList<>(appInstanceTypes);
            Collections.sort(sortedAppTypes);
            for (String type : sortedAppTypes) {
                pw.println("  " + type);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generateSummaryReport(CallGraph cg, ClassHierarchy cha, 
                                               PointerAnalysis<InstanceKey> pa, String appJar) throws IOException {
        String path = OUTPUT_DIR + "/analysis-summary.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("============================================================");
            pw.println("       WALA Static Analysis Summary for Saxon-HE");
            pw.println("============================================================");
            pw.println();
            pw.println("Analysis Tool: WALA (Watson Libraries for Analysis)");
            pw.println("Tool Repository: https://github.com/wala/WALA");
            pw.println("WALA Version: 1.8.0 (Maven Central)");
            pw.println("Analysis Type: 0-CFA Call Graph + Pointer Analysis");
            pw.println();
            pw.println("Target Project: Saxon-HE (Saxonica Saxon Home Edition)");
            pw.println("Target Repository: https://github.com/Saxonica/Saxon-HE");
            pw.println("Target JAR: " + appJar);
            pw.println();

            // Count classes
            int appClasses = 0, totalMethods = 0, totalFields = 0;
            int interfaces = 0, abstractClasses = 0, concreteClasses = 0;
            Map<String, Integer> packageMap = new HashMap<>();

            for (var cls : cha) {
                if (!cls.getClassLoader().getReference().equals(ClassLoaderReference.Application)) continue;
                appClasses++;
                if (cls.isInterface()) interfaces++;
                else if (cls.isAbstract()) abstractClasses++;
                else concreteClasses++;
                totalMethods += cls.getDeclaredMethods().size();
                totalFields += cls.getDeclaredInstanceFields().size() + cls.getDeclaredStaticFields().size();
                String pkg = getPackage(cls.getName().toString());
                packageMap.merge(pkg, 1, Integer::sum);
            }

            pw.println("=== Class Hierarchy Summary ===");
            pw.println("  Application classes: " + appClasses);
            pw.println("    - Interfaces: " + interfaces);
            pw.println("    - Abstract classes: " + abstractClasses);
            pw.println("    - Concrete classes: " + concreteClasses);
            pw.println("  Total methods declared: " + totalMethods);
            pw.println("  Total fields declared: " + totalFields);
            pw.println("  Number of packages: " + packageMap.size());
            pw.println();

            // Call graph stats
            int appNodes = 0, primordialNodes = 0, appEdges = 0, totalEdges = 0;
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodes++;
                    appEdges += cg.getSuccNodeCount(node);
                } else {
                    primordialNodes++;
                }
                totalEdges += cg.getSuccNodeCount(node);
            }

            pw.println("=== Call Graph Summary (0-CFA) ===");
            pw.println("  Total nodes: " + cg.getNumberOfNodes());
            pw.println("  Application method nodes: " + appNodes);
            pw.println("  Library/primordial nodes: " + primordialNodes);
            pw.println("  Total edges: " + totalEdges);
            pw.println("  Application-to-any edges: " + appEdges);
            pw.println();

            // Pointer analysis stats
            int totalPKs = 0;
            Set<String> appTypes = new HashSet<>();
            for (var pk : pa) {
                totalPKs++;
                var ik = pa.getPointsToSet(pk);
                if (ik == null) continue;
                for (var instance : ik) {
                    if (instance.getConcreteType().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        appTypes.add(instance.getConcreteType().getName().toString());
                    }
                }
            }

            pw.println("=== Pointer Analysis Summary ===");
            pw.println("  Total pointer keys: " + totalPKs);
            pw.println("  Application instance types discovered: " + appTypes.size());
            pw.println();

            pw.println("=== Top 10 Packages by Class Count ===");
            List<Map.Entry<String, Integer>> sortedPkgs = new ArrayList<>(packageMap.entrySet());
            sortedPkgs.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
            int limit = Math.min(10, sortedPkgs.size());
            for (int i = 0; i < limit; i++) {
                var entry = sortedPkgs.get(i);
                pw.println("  " + entry.getValue() + " classes: " + entry.getKey());
            }
            pw.println();

            pw.println("=== Output Files ===");
            pw.println("  /analysis-results/analysis-summary.txt - This summary");
            pw.println("  /analysis-results/callgraph-stats.txt - Call graph statistics");
            pw.println("  /analysis-results/class-hierarchy-report.txt - Class hierarchy details");
            pw.println("  /analysis-results/callgraph-edges.txt - Application call graph edges");
            pw.println("  /analysis-results/method-analysis.txt - Method-level analysis");
            pw.println("  /analysis-results/package-analysis.txt - Package-level analysis");
            pw.println("  /analysis-results/pointer-analysis-summary.txt - Pointer analysis summary");
            pw.println();
            pw.println("=== Analysis Complete ===");
            pw.println("Timestamp: " + java.time.Instant.now());
        }
        System.out.println("  Saved: " + path);
    }

    private static String getPackage(String className) {
        // className is in WALA format like "Lnet/sf/saxon/expr/Expression"
        String name = className;
        if (name.startsWith("L")) name = name.substring(1);
        if (name.endsWith(";")) name = name.substring(0, name.length() - 1);
        int lastSlash = name.lastIndexOf('/');
        if (lastSlash < 0) return "(default)";
        return name.substring(0, lastSlash).replace('/', '.');
    }

    private static class MethodStat {
        String signature;
        int callers;
        int callees;

        MethodStat(String signature, int callers, int callees) {
            this.signature = signature;
            this.callers = callers;
            this.callees = callees;
        }

        int getCallers() { return callers; }
        int getCallees() { return callees; }
    }

    private static class PackageStat {
        String packageName;
        int methodCount;
        int callers;
        int callees;

        PackageStat(String packageName) {
            this.packageName = packageName;
        }

        int getMethodCount() { return methodCount; }
    }
}
