            pw.println("WALA Package-Level Call Analysis for Saxon-HE");
            pw.println("========================================");
            pw.println();

            Map<String, PackageStat> packageStats = new HashMap<>();

            for (CGNode node : cg) {
                if (!node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) continue;

                String className = node.getMethod().getDeclaringClass().getName().toString();
                String pkg = getPackage(className);

                PackageStat ps = packageStats.computeIfAbsent(pkg, k -> new PackageStat(pkg));
                ps.methodCount++;
                ps.callers += cg.getPredNodeCount(node);
                ps.callees += cg.getSuccNodeCount(node);
            }

            List<PackageStat> stats = new ArrayList<>(packageStats.values());
            stats.sort(Comparator.comparingInt(PackageStat::getMethodCount).reversed());

            pw.println("=== Package Statistics ===");
            pw.println("Package | Methods | Total Callers | Total Callees");
            pw.println("--------|---------|----------------|---------------");
            for (PackageStat ps : stats) {
                pw.printf("%s | %7d | %14d | %14d%n", ps.packageName, ps.methodCount, ps.callers, ps.callees);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generatePointerAnalysisSummary(PointerAnalysis<InstanceKey> pa) throws IOException {
        String path = OUTPUT_DIR + "/pointer-analysis-summary.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Pointer Analysis Summary for Saxon-HE");
            pw.println("========================================");
            pw.println();

            int totalPointerKeys = 0;
            int appPointerKeys = 0;
            Map<String, Integer> instanceTypeCounts = new HashMap<>();
            Set<String> appInstanceTypes = new HashSet<>();

            for (var pk : pa) {
                totalPointerKeys++;
                var ik = pa.getPointsToSet(pk);
                if (ik == null) continue;
                for (var instance : ik) {
                    String concreteType = instance.getConcreteType().getName().toString();
                    instanceTypeCounts.merge(concreteType, 1, Integer::sum);
                    if (instance.getConcreteType().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        appInstanceTypes.add(concreteType);
                    }
                }
            }

            pw.println("=== Pointer Analysis Statistics ===");
            pw.println("Total pointer keys: " + totalPointerKeys);
            pw.println("Total distinct instance types: " + instanceTypeCounts.size());
            pw.println("Application instance types: " + appInstanceTypes.size());
            pw.println();

            pw.println("=== Top 50 Most Allocated Types ===");
            List<Map.Entry<String, Integer>> sortedTypes = new ArrayList<>(instanceTypeCounts.entrySet());
            sortedTypes.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
            int limit = Math.min(50, sortedTypes.size());
            for (int i = 0; i < limit; i++) {
