            pw.println("========================================");
            pw.println("WALA Call Graph Edges (Application Methods Only)");
            pw.println("========================================");
            pw.println();

            List<String> edges = new ArrayList<>();
            for (CGNode src : cg) {
                if (!src.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) continue;
                for (CGNode dst : cg) {
                    if (cg.hasEdge(src, dst)) {
                        if (dst.getMethod().getDeclaringClass().getClassLoader().getReference()
                                .equals(ClassLoaderReference.Application)) {
                            edges.add(src.getMethod().getSignature() + " -> " + dst.getMethod().getSignature());
                        }
                    }
                }
            }
            Collections.sort(edges);
            pw.println("Total application-to-application edges: " + edges.size());
            pw.println();
            for (String edge : edges) {
                pw.println(edge);
            }
        }
        System.out.println("  Saved: " + path);
    }

    private static void generateMethodAnalysis(CallGraph cg) throws IOException {
        String path = OUTPUT_DIR + "/method-analysis.txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path))) {
            pw.println("========================================");
            pw.println("WALA Method-Level Analysis for Saxon-HE");
