                    if (instance == null) continue;
                    if (instance.getConcreteType().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        appTypes.add(instance.getConcreteType().getName().toString());
                    }
                }
            }

            pw.println("=== Pointer Analysis Summary ===");
            pw.println("  Total pointer keys: " + totalPKs);
            pw.println("  Application instance types discovered: " + appTypes.size());
            pw.println();

            pw.println("=== Top 10 Packages by Class Count ===");
            List<Map.Entry<String, Integer>> sortedPkgs = new ArrayList<>(packageMap.entrySet());
