            pw.println();
            pw.println("=== Analysis Complete ===");
            pw.println("Timestamp: " + java.time.Instant.now());
        }
        System.out.println("  Saved: " + path);
    }

    private static String getPackage(String className) {
        String name = className;
        if (name.startsWith("L")) name = name.substring(1);
        if (name.endsWith(";")) name = name.substring(0, name.length() - 1);
        int lastSlash = name.lastIndexOf('/');
        if (lastSlash < 0) return "(default)";
        return name.substring(0, lastSlash).replace('/', '.');
    }

    private static class MethodStat {
        String signature;
        int callers;
        int callees;

        MethodStat(String signature, int callers, int callees) {
            this.signature = signature;
            this.callers = callers;
            this.callees = callees;
        }

        int getCallers() { return callers; }
        int getCallees() { return callees; }
    }

    private static class PackageStat {
        String packageName;
        int methodCount;
        int callers;
        int callees;

        PackageStat(String packageName) {
            this.packageName = packageName;
        }

        int getMethodCount() { return methodCount; }
    }
}
