            pw.println("       WALA Static Analysis Summary for Saxon-HE");
            pw.println("============================================================");
            pw.println();
            pw.println("Analysis Tool: WALA (Watson Libraries for Analysis)");
            pw.println("Tool Repository: https://github.com/wala/WALA");
            pw.println("WALA Version: 1.8.0 (Maven Central)");
            pw.println("Analysis Type: 0-CFA Call Graph + Pointer Analysis");
            pw.println();
            pw.println("Target Project: Saxon-HE (Saxonica Saxon Home Edition)");
            pw.println("Target Repository: https://github.com/Saxonica/Saxon-HE");
            pw.println("Target JAR: " + appJar);
            pw.println();

            int appClasses = 0, totalMethods = 0, totalFields = 0;
            int interfaces = 0, abstractClasses = 0, concreteClasses = 0;
            Map<String, Integer> packageMap = new HashMap<>();

            for (var cls : cha) {
                if (!cls.getClassLoader().getReference().equals(ClassLoaderReference.Application)) continue;
                appClasses++;
                if (cls.isInterface()) interfaces++;
                else if (cls.isAbstract()) abstractClasses++;
                else concreteClasses++;
                totalMethods += cls.getDeclaredMethods().size();
                totalFields += cls.getDeclaredInstanceFields().size() + cls.getDeclaredStaticFields().size();
                String pkg = getPackage(cls.getName().toString());
                packageMap.merge(pkg, 1, Integer::sum);
            }

            pw.println("=== Class Hierarchy Summary ===");
            pw.println("  Application classes: " + appClasses);
            pw.println("    - Interfaces: " + interfaces);
            pw.println("    - Abstract classes: " + abstractClasses);
            pw.println("    - Concrete classes: " + concreteClasses);
            pw.println("  Total methods declared: " + totalMethods);
            pw.println("  Total fields declared: " + totalFields);
            pw.println("  Number of packages: " + packageMap.size());
            pw.println();

            int appNodes = 0, primordialNodes = 0, appEdges = 0, totalEdges = 0;
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodes++;
                    appEdges += cg.getSuccNodeCount(node);
                } else {
                    primordialNodes++;
                }
                totalEdges += cg.getSuccNodeCount(node);
            }

            pw.println("=== Call Graph Summary (0-CFA) ===");
            pw.println("  Total nodes: " + cg.getNumberOfNodes());
            pw.println("  Application method nodes: " + appNodes);
            pw.println("  Library/primordial nodes: " + primordialNodes);
            pw.println("  Total edges: " + totalEdges);
            pw.println("  Application-to-any edges: " + appEdges);
            pw.println();

            int totalPKs = 0;
            Set<String> appTypes = new HashSet<>();
            for (PointerKey pk : pa.getPointerKeys()) {
                totalPKs++;
                var pointsToSet = pa.getPointsToSet(pk);
                if (pointsToSet == null) continue;
                for (InstanceKey instance : pointsToSet) {
                    if (instance == null) continue;
                    if (instance.getConcreteType().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        appTypes.add(instance.getConcreteType().getName().toString());
                    }
                }
            }

            pw.println("=== Pointer Analysis Summary ===");
            pw.println("  Total pointer keys: " + totalPKs);
            pw.println("  Application instance types discovered: " + appTypes.size());
            pw.println();

            pw.println("=== Top 10 Packages by Class Count ===");
            List<Map.Entry<String, Integer>> sortedPkgs = new ArrayList<>(packageMap.entrySet());
            sortedPkgs.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
            int limit = Math.min(10, sortedPkgs.size());
            for (int i = 0; i < limit; i++) {
                var entry = sortedPkgs.get(i);
                pw.println("  " + entry.getValue() + " classes: " + entry.getKey());
            }
            pw.println();

            pw.println("=== Output Files ===");
            pw.println("  /analysis-results/analysis-summary.txt - This summary");
            pw.println("  /analysis-results/callgraph-stats.txt - Call graph statistics");
            pw.println("  /analysis-results/class-hierarchy-report.txt - Class hierarchy details");
            pw.println("  /analysis-results/callgraph-edges.txt - Application call graph edges");
            pw.println("  /analysis-results/method-analysis.txt - Method-level analysis");
            pw.println("  /analysis-results/package-analysis.txt - Package-level analysis");
            pw.println("  /analysis-results/pointer-analysis-summary.txt - Pointer analysis summary");
            pw.println();
            pw.println("=== Analysis Complete ===");
            pw.println("Timestamp: " + java.time.Instant.now());
        }
        System.out.println("  Saved: " + path);
    }

    private static String getPackage(String className) {
        String name = className;
        if (name.startsWith("L")) name = name.substring(1);
        if (name.endsWith(";")) name = name.substring(0, name.length() - 1);
        int lastSlash = name.lastIndexOf('/');
        if (lastSlash < 0) return "(default)";
        return name.substring(0, lastSlash).replace('/', '.');
    }

    private static class MethodStat {
        String signature;
        int callers;
        int callees;

        MethodStat(String signature, int callers, int callees) {
            this.signature = signature;
            this.callers = callers;
            this.callees = callees;
        }

        int getCallers() { return callers; }
        int getCallees() { return callees; }
    }

    private static class PackageStat {
        String packageName;
        int methodCount;
        int callers;
        int callees;

        PackageStat(String packageName) {
            this.packageName = packageName;
        }

        int getMethodCount() { return methodCount; }
    }
}
JAVAEOF
